/** Contract-based test harness for the compute entry point
  *
  * @param api_apActiveClearInhibit incoming data port
  * @param api_apGuidanceRequest incoming data port
  * @param api_fdDisposition incoming data port
  * @param api_qualifiedAttitude incoming data port
  */
pub fn testComputeCB(
  api_apActiveClearInhibit: bool,
  api_apGuidanceRequest: FlightStack::ApGuidanceRequestValue,
  api_fdDisposition: FlightStack::QualifiedFdAndSyncDisposition,
  api_qualifiedAttitude: FlightStack::QualifiedAttitude) -> HarnessResult
{
  // Initialize the app
  crate::referenceManager_behavior_initialize();

  // [PutInPorts]: Set values on the input ports
  put_apActiveClearInhibit(api_apActiveClearInhibit);
  put_apGuidanceRequest(api_apGuidanceRequest);
  put_fdDisposition(api_fdDisposition);
  put_qualifiedAttitude(api_qualifiedAttitude);

  // [InvokeEntryPoint]: Invoke the entry point
  crate::referenceManager_behavior_timeTriggered();

  return HarnessResult::Passed
}

/** Contract-based test harness for the compute entry point
  */
pub fn testComputeCB_container(container: PreStateContainer) -> HarnessResult
{
  return testComputeCB(container.api_apActiveClearInhibit, container.api_apGuidanceRequest, container.api_fdDisposition, container.api_qualifiedAttitude)
}

